def squash(s: str) -> str:
    result = []
    i = 0
    n = len(s)

    while i < n:
        j = i + 1
        while j < n and s[j] == s[i]:
            j += 1

        c = s[i]
        escaped = "\\" + c if "0" <= c <= "9" or c == "\\" else c
        length = j - i

        if length >= 3:
            result.append(str(length) + escaped)
        else:
            result.append(escaped * length)

        i = j

    return "".join(result)
